#include <stdio.h>
#include <stdlib.h>

struct Node {
    int key;
    struct Node *left;
    struct Node *right;
};

static struct Node *make_node(int key)
{
    struct Node *node = malloc(sizeof *node);
    if (node == NULL) {
        return NULL;
    }
    node->key = key;
    node->left = NULL;
    node->right = NULL;
    return node;
}

static void preorder(const struct Node *node)
{
    if (node == NULL) return;
    printf("%d ", node->key);
    preorder(node->left);
    preorder(node->right);
}

static void inorder(const struct Node *node)
{
    if (node == NULL) return;
    inorder(node->left);
    printf("%d ", node->key);
    inorder(node->right);
}

static void postorder(const struct Node *node)
{
    if (node == NULL) return;
    postorder(node->left);
    postorder(node->right);
    printf("%d ", node->key);
}

static void destroy_tree(struct Node *node)
{
    if (node == NULL) return;
    destroy_tree(node->left);
    destroy_tree(node->right);
    free(node);
}

int main(void)
{
    struct Node *root = make_node(8);
    if (root == NULL) return 1;

    root->left = make_node(3);
    if (root->left == NULL) {
        destroy_tree(root);
        return 1;
    }

    root->right = make_node(10);
    if (root->right == NULL) {
        destroy_tree(root);
        return 1;
    }

    root->left->left = make_node(1);
    if (root->left->left == NULL) {
        destroy_tree(root);
        return 1;
    }

    root->left->right = make_node(6);
    if (root->left->right == NULL) {
        destroy_tree(root);
        return 1;
    }

    printf("Preorder: ");
    preorder(root);
    printf("\nInorder: ");
    inorder(root);
    printf("\nPostorder: ");
    postorder(root);
    putchar('\n');

    destroy_tree(root);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

static void print_children(const int values[], size_t count, size_t index)
{
    if (index >= count) {
        return;
    }

    printf("Node %d", values[index]);

    if (count >= 2U && index <= (count - 2U) / 2U) {
        size_t left = 2U * index + 1U;
        size_t right = left + 1U;

        if (left < count) {
            printf(", left child %d", values[left]);
        }
        if (right < count) {
            printf(", right child %d", values[right]);
        }
    }
    putchar('\n');
}

int main(void)
{
    const int values[] = {8, 3, 10, 1, 6, 9, 14};
    const size_t count = sizeof values / sizeof values[0];

    puts("Level-order traversal:");
    for (size_t i = 0U; i < count; ++i) {
        printf("%d ", values[i]);
    }
    putchar('\n');

    puts("Parent and child relationships:");
    for (size_t i = 0U; i < count; ++i) {
        print_children(values, count, i);
    }

    return 0;
}
